from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];SRC=ROOT/'artifacts/orion-qg-qg42b-pytket.json';GEN=ROOT/'artifacts/orion-qg-qg42b-generic-verification.json';OUT=ROOT/'artifacts/orion-qg-qg42b-native-verification.json';TOKEN='ORIONQG_QG42B_NATIVE=';TERMS={'QG42B_PYTKET_ALL_COLLISIONS_SELECTION_SEPARATION_BOTH_TOPOLOGIES_MACHINE_CHECKED','QG42B_PYTKET_ALL_COLLISIONS_SELECTION_SEPARATION_ONE_TOPOLOGY_ONLY','QG42B_PYTKET_ALL_COLLISIONS_NO_SELECTION_SEPARATION'}
